D.DynamicSpellTexts[228728]={Description={Key="cf13f8efe3f4213e:276",Text="海拉的触须会出现在平台的前方或后方。\r\n\r\n数秒后，触须击打地面，造成{1}点自然伤害，由被击中的所有敌人分摊。\r\n\r\n如果触须毫无障碍地击中地面，将施放横扫平台的冲击波，对所有玩家造成{1}点自然伤害。",Count=2,Constants={},Equals={{1,2}}}}
D.DynamicSpellTexts[228729]={Description={Key="a97922ca6759b10f:128",Text="击败一名城堡仆人后，其他成员恢复全部生命值，并且在余下的战斗中伤害提高{1}%。此效果可以叠加。",Count=1,Constants={},Equals={}},Aura={Key="d84f1195201e7eee:30",Text=S[20588],Count=1,Constants={},Equals={}}}
